<!DOCTYPE html>
<html lang="fr">
<head><script>
(function(){
  // Le WebView Android n'implémente pas certaines API présentes dans Chrome
  // (synthèse vocale notamment). On fournit des remplaçants inertes pour que
  // le contenu ne plante jamais dessus — la fonctionnalité ne marchera juste
  // pas, mais le reste de l'app continue de fonctionner normalement.
  if(typeof window.speechSynthesis === 'undefined'){
    window.speechSynthesis = {
      speak: function(){}, cancel: function(){}, pause: function(){}, resume: function(){},
      getVoices: function(){ return []; }, speaking:false, pending:false, paused:false,
      onvoiceschanged: null, addEventListener: function(){}, removeEventListener: function(){}
    };
  }
  if(typeof window.SpeechSynthesisUtterance === 'undefined'){
    window.SpeechSynthesisUtterance = function(text){ this.text = text; };
  }

  // ── Filet d'erreurs universel ───────────────────────────────────────────
  // N'importe quel projet ouvert ici (même un qu'on ne connaît pas encore et
  // que l'outil ne sait pas gérer) doit voir ses plantages affichés au lieu
  // de rester silencieux. On les fait remonter vers la bannière de l'app.
  function reportToParent(message){
    try {
      if(window.parent && window.parent.showErrorBanner) window.parent.showErrorBanner(message);
    } catch(e){}
  }
  window.addEventListener('error', function(e){
    reportToParent('Erreur dans le projet : ' + (e && e.message ? e.message : 'inconnue'));
  });
  window.addEventListener('unhandledrejection', function(e){
    const r = e && e.reason;
    reportToParent('Erreur dans le projet : ' + (r && r.message ? r.message : (typeof r === 'string' ? r : 'inconnue')));
  });

  // ── Pont universel téléchargement/partage ──────────────────────────────
  // N'importe quel fichier HTML chargé ici (même un exemple sans aucun code
  // pour ça) doit pouvoir télécharger/partager exactement comme le fait
  // l'application elle-même (chemin natif via AppBridge), sans rien connaître
  // de son existence. On intercepte les mécanismes web standards et on les
  // redirige silencieusement vers le pont natif si disponible.
  function toBase64(blob, cb){
    const reader = new FileReader();
    reader.onloadend = function(){ cb(reader.result.split(',')[1] || ''); };
    reader.readAsDataURL(blob);
  }
  function bridge(){ try { return window.parent && window.parent.AppBridge; } catch(e){ return null; } }

  // De nombreux scripts d'export font : const url=URL.createObjectURL(blob);
  // a.href=url; a.click(); URL.revokeObjectURL(url); — le revoke est appelé
  // en synchrone juste après le click(), alors que notre interception fait un
  // fetch() ASYNCHRONE de ce même blob: pour le convertir en base64. Sans ce
  // correctif, le blob est souvent déjà révoqué quand le fetch s'exécute →
  // le fetch échoue → le catch (silencieux) avale l'erreur → "rien ne se
  // passe". On retarde le revoke réel pour laisser le temps au fetch de lire
  // les données ; ça ne change rien pour le reste (mémoire libérée quelques
  // secondes plus tard au lieu d'immédiatement, sans impact visible).
  const nativeRevokeObjectURL = URL.revokeObjectURL.bind(URL);
  URL.revokeObjectURL = function(url){ setTimeout(function(){ nativeRevokeObjectURL(url); }, 4000); };

  // Intercepte tout téléchargement demandé via une ancre <a download> ou
  // <a href="blob:...">/"data:...">, quel que soit le chemin technique
  // emprunté par la page pour le déclencher. Fonction partagée par les deux
  // mécanismes de détection ci-dessous. Retourne une Promise (pas un bool) :
  // resolve(true) si interceptée+traitée, resolve(false) si pas concernée,
  // reject en cas d'échec réel — pour permettre un vrai fallback (voir plus
  // bas) au lieu d'un blocage silencieux.
  function tryInterceptAnchor(a){
    if(!a || !a.href) return Promise.resolve(false);
    const isBlobOrData = /^(blob:|data:)/i.test(a.href);
    const wantsDownload = a.hasAttribute('download');
    if(!isBlobOrData && !wantsDownload) return Promise.resolve(false);
    const br = bridge();
    if(!br) return Promise.resolve(false); // pas de pont natif dispo (ex: prévisualisation web classique) : on laisse faire le navigateur
    const filename = a.getAttribute('download') || (a.href.split('/').pop() || 'fichier').split('?')[0] || 'fichier';
    return fetch(a.href).then(r => r.blob()).then(blob => new Promise(function(resolve, reject){
      toBase64(blob, function(b64){
        try { br.downloadFile(b64, filename, blob.type || 'application/octet-stream'); resolve(true); }
        catch(e){ reject(e); }
      });
    }));
  }

  function isCandidateAnchor(a){
    if(!a || !a.href) return false;
    return /^(blob:|data:)/i.test(a.href) || a.hasAttribute('download');
  }

  // Cas 1 : clic utilisateur réel sur une ancre visible dans le DOM. On doit
  // annuler le comportement par défaut de façon SYNCHRONE (preventDefault ne
  // marche pas après coup) dès qu'on tente une interception ; si celle-ci
  // échoue en réalité (promesse rejetée), on relance un clic natif en
  // fallback au lieu de laisser l'échec totalement silencieux.
