    if(!isCandidateAnchor(a)) return;
    ev.preventDefault();
    tryInterceptAnchor(a).then(function(handled){
      if(!handled) nativeAnchorClick.apply(a, []);
    }).catch(function(){ try{ nativeAnchorClick.apply(a, []); }catch(e){} });
  }, true);

